struct Finite:g::L2DramCompletionBackend{
 sg_hbf::Clock clock;U delay;g::L2DramRuntimeStatistics stats;std::map<U,g::L2DramRequest>live;J requests=J::array(),returns=J::array();
 Finite(U d,sg_hbf::Clock c):clock(c),delay(d){}
 U issue_cycle_to_ps(U c)const override{return clock.issue_ps(c);}
 void enqueue(const g::L2DramRequest&r)override{check(try_enqueue(r,r.issue_cycle),"finite admission");}
 bool try_enqueue(const g::L2DramRequest&r,U at)override{
  check(at>=r.issue_cycle&&r.issue_time_ps==issue_cycle_to_ps(r.issue_cycle),"actual request time");if(live.size()==2)return false;
  check(live.emplace(r.request_id,r).second,"unique actual request");requests.push_back({r.request_id,r.issue_cycle,r.address,r.key.line_addr,r.sm_id,r.l2_subpartition_id,r.bytes,int(r.cause)});
  if(r.cause==g::L2DramRequestCause::FILL_READ){++stats.fill_requests;stats.fill_bytes+=r.bytes;}else{++stats.writeback_requests;stats.writeback_bytes+=r.bytes;}stats.peak_queue_depth=std::max<U>(stats.peak_queue_depth,live.size());return true;
 }
 std::vector<g::L2DramCompletion> step(U at)override{
  std::vector<g::L2DramCompletion>out;for(auto i=live.begin();i!=live.end();){auto r=i->second;U due=r.issue_cycle+delay;if(due>at){++i;continue;}bool w=r.cause==g::L2DramRequestCause::DIRTY_WRITEBACK;
  out.push_back({r.request_id,r.source_sequence,r.issue_cycle,r.issue_time_ps,due,r.key,w});returns.push_back({r.request_id,due,at});i=live.erase(i);if(w){++stats.writeback_completions;stats.writeback_completed_bytes+=r.bytes;}else{++stats.fill_completions;stats.fill_completed_bytes+=r.bytes;}}
  return out;
 }
 const g::L2DramRuntimeStatistics& statistics()const override{return stats;}
 std::size_t queue_depth()const override{return live.size();}
 std::size_t admission_capacity()const override{return 2;}
};
struct Mapper:g::L2DramAddressMapper{static constexpr U base=1ULL<<40;U map(const g::CacheLineKey&k)const override{check(k.line_addr>=base,"in extent");return k.line_addr-base;}};
struct Observe:g::L2RuntimeObserver{J decisions=J::array(),fills=J::array();void on_l2_decision(const g::L2DecisionEvent&e)override{decisions.push_back({e.node_id,e.accept_cycle,e.decision_cycle,int(e.outcome),e.line_addr});}void on_l2_fill(const g::L2FillEvent&e)override{fills.push_back({e.line_addr,e.allocate_cycle,e.complete_cycle,int(e.eviction_kind),e.victim_line_addr});}};
struct Driver{
 g::L2DramCompletionBackend&backend;g::SimulatorConfig cfg;Mapper mapper;Observe obs;g::L2Cache cache;U now=0;unsigned q;int next=0;std::set<int>accepted,completed;J callbacks=J::array();g::L2Cache::EpochServiceStatistics epoch;
 Driver(g::L2DramCompletionBackend&b,g::SimulatorConfig c,unsigned quantum):backend(b),cfg(c),cache(c.l2_cache_size_bytes,c.l2_line_size_bytes,c.l2_hit_latency_cycles,c.l2_bandwidth_bytes_per_cycle,c.l2_write_bandwidth_bytes_per_cycle,c.l2_queue_depth,c.l2_bypass_cache,0,c.l2_miss_penalty_cycles,c.core_frequency_mhz,c.dram_frequency_mhz,c.memory_model_semantics,c.per_sm_l1,&backend,&mapper,c.l2_geometry),q(quantum){cache.enable_shared_cache(288);cache.begin_kernel();cache.set_runtime_observer(&obs);}
 int send(U addr,bool write=false,bool bypass=false){int id=next++;g::ExplicitMemorySubop sub;sub.requested_bytes=2;sub.ranges={{0,addr,2}};sub.source_member_ordinals={0};std::vector<g::ExplicitMemorySubop>subs{sub};g::L2LineRequest r;r.completion_token=id;r.native_key=r.cache_key={1,addr};r.cycle=now;r.is_write=write;r.sm_id=3;r.subpartition_id=2;r.bypass_l1=bypass;r.source_matrix_id=1;r.source_subop_index=0;r.source_subops=subs;check(cache.enqueue_line_request(r),"one legitimate ingress");check(accepted.insert(id).second,"unique acceptance");return id;}
 void pump(){now+=q;std::vector<int>done;if(q==1)done=cache.step(now);else{cache.require_memory_epoch_span(now,q,backend);auto batch=backend.step(now);done=cache.service_epoch(now,q,backend,batch,&epoch);}for(int id:done){check(accepted.count(id)&&completed.insert(id).second,"exact completion callback");callbacks.push_back({id,now});}cache.end_cycle(g::checked_cycle(now));auto d=cache.dirty_sector_snapshot();check(d.dirty_sector_ledger_closed&&d.writeback_byte_ledger_closed,"actual dirty/WB closure");check(now<2000000,"bounded component runtime");}
 void drain(){do{pump();}while(!cache.is_quiescent());check(accepted==completed&&backend.queue_depth()==0&&cache.per_sm_l1_readiness().live_tickets==0,"all callbacks/tickets/backend closed");}
 J result(){auto d=cache.dirty_sector_snapshot();auto&s=backend.statistics();check(d.dirty_sector_creations==d.evicted_dirty_sectors+d.resident_dirty_sectors,"I0+C=E+F");check(s.fill_bytes==128*s.fill_requests&&s.writeback_bytes==32*d.evicted_dirty_sectors&&s.fill_bytes==s.fill_completed_bytes&&s.writeback_bytes==s.writeback_completed_bytes,"128B fill/32B dirty physical ledger");return{{"runtime",serial(cache.runtime_statistics())},{"dirty",serial(d)},{"readiness",serial(cache.per_sm_l1_readiness())},{"backend",serial(s)},{"decisions",obs.decisions},{"fills",obs.fills},{"callbacks",callbacks},{"accepted",accepted.size()},{"completed",completed.size()},{"end_cycle",now},{"policy",cache.shared_cache_report<J>()}};}
};
g::SimulatorConfig active(g::SimulatorConfig c){c.per_sm_l1.sector_validity=true;return c;}
J sequence(g::SimulatorConfig c,unsigned q,U delay){Finite b(delay,{40000,87});Driver d(b,active(c),q);U a=Mapper::base;d.send(a);d.drain();U miss_callback=d.now;check(!b.requests.empty(),"miss reaches external backend");U issue=b.requests[0][1];U due=issue+delay;check(miss_callback>=due&&miss_callback-due<q,"external due has only epoch visibility rounding; no604/hit floor");U l1begin=d.now;d.send(a);d.drain();check(d.now>=l1begin+U(c.per_sm_l1.hit_latency_cycles)&&d.now-(l1begin+c.per_sm_l1.hit_latency_cycles)<q,"actual L1 hit latency");d.cache.begin_kernel();d.send(a);d.drain();U decision=d.obs.decisions.back()[2];check(d.now>=decision+U(c.l2_hit_latency_cycles)&&d.now-(decision+c.l2_hit_latency_cycles)<q,"actual L2 hit total without duplicate L1 charge");d.send(a,true);d.drain();J out=d.result();out["requests"]=b.requests;out["returns"]=b.returns;out["miss_callback"]=miss_callback;out["miss_issue"]=issue;check(b.requests.size()==1&&b.requests[0][4]==3&&b.requests[0][5]==2&&b.requests[0][2]==0&&b.requests[0][3]==a,"service mapper and caller routing metadata preserved");return out;}
