J geometry(){g::L2Geometry n(g::L2GeometryConfig::accelsim_rtx4000_ada(),40*1024*1024,128),old(g::L2GeometryConfig::paper_ada_l2_v1(),40*1024*1024,128);check(n.group_count()==20480&&n.capacity_per_group()==16&&n.total_lines()==327680,"40MiB/20x1024x16");std::vector<U>counts(20480);U differs=0;for(U a=0;a<40*1024*1024;a+=128){U chip=(a/256)%10,rest=((a/256)/10)*256+(a%256),sub=chip*2+((rest/128)%2),local=((a/256)/10)*128+(a%128),set=((local/128)^(local/131072))%1024;check(n.partition(a)==sub&&n.set(a)==set&&n.group(a)==sub*1024+set,"independent integer mapping oracle");++counts[n.group(a)];differs+=n.group(a)!=old.group(a);}for(U c:counts)check(c==16,"entire40MiB uniformly occupies16ways per group");check(differs>0,"new mapping differs from old PAPER");g::L2GroupedLru<U>lru(g::L2GeometryConfig::accelsim_rtx4000_ada(),40*1024*1024,128);std::vector<U>keys;U target=n.group(Mapper::base);for(U a=Mapper::base;keys.size()<17;a+=128)if(n.group(a)==target)keys.push_back(a);std::vector<decltype(lru)::iterator>its;for(unsigned i=0;i<16;++i)its.push_back(lru.insert_mru(keys[i],keys[i]));check(*lru.victim(keys.back())==keys[0],"actual grouped16way eviction");lru.touch_lru(keys[5],its[5]);check(*lru.victim(keys.back())==keys[5],"existing h288 LRU-end action preserved");lru.erase(keys[5],its[5]);lru.insert_lru(keys.back(),keys.back());check(*lru.victim(keys.back())==keys.back(),"existing EF insertion-LRU preserved");return{{"line_checks",327680},{"groups",20480},{"ways",16},{"groups_differing_from_PAPER",differs},{"congruent_addresses",keys}};}
J physical(const char*path,const J&geo){sg_hbf::Clock clock(40000,87);sg_hbf::MemoryPathBackend b(clock,sg_hbf::native_config_file(path),{},4096,32,{sg_hbf::DrainMode::Independent,1});Driver d(b,active(g::make_ada_cosim_alignment_config("tuner-v1")),1);for(std::size_t i=0;i<geo["congruent_addresses"].size();++i){d.send(geo["congruent_addresses"][i],i==0,true);d.drain();}auto out=d.result();b.finalize();auto p=b.physical_statistics();auto a=b.physical_admission_statistics();auto t=b.path_statistics();check(p.read_bytes==2176&&p.write_bytes==32,"actual HBFSIM exact fill/WB bytes");check(out["dirty"]["evicted_dirty_sectors"]==1&&out["dirty"]["resident_dirty_sectors"]==0,"actual grouped dirty victim");check(a.accepted==18&&a.completed==18&&a.reserved_bursts==0&&b.queue_depth()==0&&t.outer_accepted==18&&t.outer_delivered==18,"actual physical credits/outer completion");out["physical"]={{"read_bytes",p.read_bytes},{"write_bytes",p.write_bytes},{"finish_ns",p.finish_ns},{"accepted",a.accepted},{"completed",a.completed},{"reserved_bursts",a.reserved_bursts}};return out;}
